class Solution {
    private List<Integer> group(int[] values,int parity){
        List<Integer> result=new ArrayList<>();
        for(int value:values)if(value%2==parity)result.add(value);
        Collections.sort(result);
        return result;
    }
    public long makeSimilar(int[] nums,int[] target){
        long difference=0;
        for(int parity=0;parity<2;parity++){
            List<Integer> a=group(nums,parity),b=group(target,parity);
            for(int i=0;i<a.size();i++)difference+=Math.abs((long)a.get(i)-b.get(i));
        }
        return difference/4;
    }
}

code.kotlin:
class Solution {
    fun makeSimilar(nums:IntArray,target:IntArray):Long{
        var difference=0L;
        for(parity in 0..1){
            val a=nums.filter{
                it%2==parity
            }.sorted();
            val b=target.filter{
                it%2==parity
            }.sorted();
            for(i in a.indices)difference+=kotlin.math.abs(a[i].toLong()-b[i])
        };
        return difference/4
    }
}

